import CoreText
import Foundation
import SwiftUI

/// The gallery's contents, generated by scripts/build-catalog.py, plus Apple's fonts from
/// AppleFonts.json, which TypecaskUITests/ApplePreviewRenderer.swift generates.
struct Catalog: Decodable {
    let sampleText: String
    /// Nerd Fonts icons, shown under the sample for casks whose `glyphs` is set.
    let glyphSample: String
    let casks: [Cask]
    private(set) var appleFonts: [AppleFontFamily] = []

    private enum CodingKeys: String, CodingKey {
        case sampleText, glyphSample, casks
    }

    /// Only decodes JSON. Preview fonts load as cards appear (see PreviewFonts): registering all of them
    /// here held up the first frame for most of a second, and taps before then went nowhere.
    static let bundled: Catalog = {
        guard var catalog: Catalog = decode("Catalog") else {
            fatalError("Catalog.json is missing or malformed; run scripts/build-catalog.py")
        }
        catalog.appleFonts = decode("AppleFonts") ?? []
        return catalog
    }()

    private static func decode<Value: Decodable>(_ resource: String) -> Value? {
        guard let url = Bundle.main.url(forResource: resource, withExtension: "json"),
              let data = try? Data(contentsOf: url) else { return nil }
        return try? JSONDecoder().decode(Value.self, from: data)
    }
}

/// A Homebrew font cask.
struct Cask: Decodable, Identifiable, Hashable {
    let token: String
    let name: String
    let homepage: URL
    let installs: Int
    let bytes: Int64
    /// How many fonts the cask holds, whether or not this build ships them.
    let fonts: Int
    /// Asset catalog names of the cask's font files, empty when `--fonts` left them out of this build.
    let assets: [String]
    /// PostScript name of the face previewed in the gallery, used to check whether the cask is installed.
    let primaryFont: String
    /// How the primary face is drawn, which the sidebar filters on.
    let style: DesignStyle
    let previewFile: String
    /// The On-Demand Resources tag the cask's fonts download under. Usually the token, but small casks
    /// share a pack once there are more casks than Apple allows packs; absent when the build doesn't
    /// ship the cask's fonts.
    let pack: String?
    /// Whether the cask is patched with Nerd Fonts' icons, which its preview then includes.
    let glyphs: Bool
    /// Google Fonts' description of the family, as Markdown.
    let description: String?
    /// The family's designers, per Google Fonts, who often wrote its description.
    let designers: [String]?
    /// Homebrew's version of the cask, or the font's own where the cask always takes the latest.
    let version: String?
    /// The primary face's version string, which an installed copy's is compared with to offer an update.
    let fontVersion: String?

    var id: String { token }
    /// Whether this build carries the cask's fonts. Only a bundled cask has an On-Demand Resources tag
    /// to download, so only a bundled cask can be installed.
    var isBundled: Bool { !assets.isEmpty }
    var license: String? {
        guard let url = Bundle.main.url(forResource: token, withExtension: "txt"),
              let text = try? String(contentsOf: url, encoding: .utf8) else { return nil }
        return text.unwrappingHardLineBreaks()
    }
}

/// The casks' preview fonts, each read from Previews/ the first time a card draws it.
///
/// They are used as CTFonts rather than registered by name, which also keeps them out of the
/// app's font list. 40 of them load in about 2 ms.
enum PreviewFonts {
    private static var descriptors: [String: CTFontDescriptor] = [:]

    static func font(_ file: String, size: CGFloat) -> Font {
        guard let descriptor = descriptor(file) else { return .system(size: size) }
        return Font(CTFontCreateWithFontDescriptor(descriptor, size, nil))
    }

    private static func descriptor(_ file: String) -> CTFontDescriptor? {
        if let descriptor = descriptors[file] {
            return descriptor
        }
        guard let url = Bundle.main.url(forResource: file, withExtension: nil),
              let found = CTFontManagerCreateFontDescriptorsFromURL(url as CFURL) as? [CTFontDescriptor],
              let descriptor = found.first else { return nil }
        descriptors[file] = descriptor
        return descriptor
    }
}

extension String {
    /// Rejoins lines that a license file wrapped at 70 or 80 columns, so the text wraps to the screen
    /// instead. Blank lines still separate paragraphs, and a line that starts a list item, a copyright
    /// notice or an indented block keeps its break.
    func unwrappingHardLineBreaks() -> String {
        let keepsBreak = /^\s*(?:[-*•]|\d+[.)]|\(?[a-zA-Z0-9]{1,3}\)|[a-zA-Z][.)]\s|Copyright\b|\(c\)|©|\s{4})/
        var paragraphs: [String] = []
        var current = ""
        for line in split(separator: "\n", omittingEmptySubsequences: false) {
            let line = line.replacing("\r", with: "")
            if line.allSatisfy(\.isWhitespace) {
                if !current.isEmpty {
                    paragraphs.append(current)
                    current = ""
                }
            } else if current.isEmpty {
                current = String(line)
            } else if line.prefixMatch(of: keepsBreak) != nil {
                current += "\n" + line
            } else {
                current += " " + line.trimmingCharacters(in: .whitespaces)
            }
        }
        if !current.isEmpty {
            paragraphs.append(current)
        }
        return paragraphs.joined(separator: "\n\n")
    }
}
